package com.gymie.shared.domain

import kotlinx.serialization.Serializable

@Serializable
data class AuthTokens(
    val accessToken: String,
    val refreshToken: String,
    val tokenType: String = "Bearer",
    val emailVerificationToken: String? = null,
)

@Serializable
data class RefreshRequest(
    val refreshToken: String,
)

@Serializable
data class AccessTokenResponse(
    val accessToken: String,
    val refreshToken: String,
    val tokenType: String = "Bearer",
)

@Serializable
data class RegisterRequest(
    val email: String,
    val password: String,
    val nickname: String,
    val displayName: String,
    val inviteToken: String,
    /**
     * Optional; the default `null` is what kotlinx.serialization's default `encodeDefaults = false`
     * uses to omit the key entirely when unset, so an unchosen gender registers exactly as before
     * this field existed (KAN-347 task 10).
     */
    val gender: Gender? = null,
)

@Serializable
data class InvitePreview(
    val email: String,
)

@Serializable
data class LoginRequest(
    val email: String,
    val password: String,
)

@Serializable
data class OAuthExchangeRequest(
    val code: String,
)

@Serializable
data class VerifyEmailRequest(
    val token: String,
)

@Serializable
data class ForgotPasswordRequest(
    val email: String,
)

@Serializable
data class ForgotPasswordResponse(
    val resetToken: String? = null,
)

@Serializable
data class ResetPasswordRequest(
    val token: String,
    val newPassword: String,
)

@Serializable
data class CurrentUser(
    /** The effective account's id — defaulted so every existing fixture keeps decoding. */
    val userId: String = "",
